  static String compact(String x) => x
      .replaceAll(RegExp(r'<[^>]*>', dotAll: true), ' ')
      .replaceAll('&nbsp;', ' ')
      .replaceAll('&#160;', ' ')
      .replaceAll('&amp;', '&')
      .replaceAll('&lt;', '<')
      .replaceAll('&gt;', '>')
      .replaceAll(RegExp(r'\s+'), '');
  static List<Map<String, dynamic>> parse({
    required Map<String, String> raw,
    required Map<String, Uri> uris,
    required String receipt,
    required String corp,
    required DateTime start,
    required DateTime end,
    required bool consolidated,
  }) {
    void guard(bool ok, String why) {
      if (!ok) throw FormatException('KoreanRe exact current: $why');
    }

    guard(
      receipt == '20230323001465' &&
          corp == '00113191' &&
          start == DateTime.utc(2022) &&
          end == DateTime.utc(2022, 12, 31),
      'issuer/period mismatch',
    );
    final basis = consolidated ? 'cfs' : 'ofs';
    final profile = profiles[basis] as Map<String, dynamic>;
    final year = profile['year'] as int;
    guard(raw.length == 3 && uris.length == 3, 'own source set mismatch');
    for (final v in profile['sources'] as List) {
      final label = v['label'] as String;
      guard(
        raw[label] != null &&
            uris[label].toString() == v['url'] &&
            sha256.convert(utf8.encode(raw[label]!)).toString() == v['sha256'],
        'own URI/SHA mismatch',
      );
    }
    final ids = RegExp(r"openCorpInfoNew\('([0-9]{8})'")
        .allMatches(raw['shell']!)
        .map((v) => v[1])
        .toSet();
    guard(ids.length == 1 && ids.single == corp, 'own shell corp missing');
    guard(
      compact(raw['cover']!).contains('코리안리재보험') &&
          compact(raw['cover']!).contains('$year.01.01'),
      'own cover/current period missing',
    );
    final nodes =
        RegExp(
              r'''(node[12])\['text'\]\s*=\s*"([^"]+)";(.*?)(?=node[12]\['text'\]|$)''',
              dotAll: true,
            )
            .allMatches(raw['shell']!)
            .where(
              (v) => compact(v[2]!) == (consolidated ? '2.연결재무제표' : '4.재무제표'),
            )
            .toList();
    guard(nodes.length == 1, 'unique own OFS node missing');
    final attributes = <String, String>{};
    for (final v in RegExp(
      r'''node[12]\['(rcpNo|dcmNo|eleId|offset|length|dtd)'\]\s*=\s*"([^"]+)"''',
    ).allMatches(nodes.single[3]!)) {
      guard(!attributes.containsKey(v[1]), 'duplicate source coordinate');
      attributes[v[1]!] = v[2]!;
    }
    guard(
      attributes.length == 6 &&
          attributes.entries.every(
            (v) => uris[basis]!.queryParameters[v.key] == v.value,
          ),
      'own OFS chain mismatch',
    );
    final tables =
        RegExp(r'<table\b[^>]*>([\s\S]*?)</table>', caseSensitive: false)
            .allMatches(raw[basis]!)
            .map(
              (table) =>
                  RegExp(r'<tr\b[^>]*>([\s\S]*?)</tr>', caseSensitive: false)
                      .allMatches(table[1]!)
                      .map(
                        (row) =>
                            RegExp(
                                  r'<t[dh]\b[^>]*>([\s\S]*?)</t[dh]>',
                                  caseSensitive: false,
                                )
                                .allMatches(row[1]!)
                                .map((cell) => compact(cell[1]!))
                                .toList(),
                      )
                      .toList(),
            )
            .toList();
    guard(
      jsonEncode(tables) == jsonEncode(profile['tables']),
      'physical whole source rows changed',
    );
    for (final v in profile['currentHeaders'] as List) {
      guard(
        jsonEncode(tables[v['table'] as int]) == jsonEncode(v['expected']),
        'own current header/unit missing',
      );
    }
    BigInt? money(String x) {
      if (x == '' || x == '-') return null;
      guard(
        RegExp(
          r'^(?:-?(?:0|[1-9][0-9]*|[1-9][0-9]{0,2}(?:,[0-9]{3})+)|\((?:0|[1-9][0-9]*|[1-9][0-9]{0,2}(?:,[0-9]{3})+)\))$',
        ).hasMatch(x),
        'invalid printed monetary group',
      );
      return BigInt.parse(
        x.replaceAll(',', '').replaceAll('(', '-').replaceAll(')', ''),
      );
    }

    for (final eq in profile['checks'] as List) {
      final total = eq['total'] as Map;
      final current = money(
        tables[total['table'] as int][total['row'] as int][total['column']
            as int],
      );
      guard(current != null, 'unprinted total');
      var sum = BigInt.zero;
      var missing = 0;
      for (final term in eq['terms'] as List) {
        final value = money(
          tables[term['table'] as int][term['row'] as int][term['column']
              as int],
        );
        if (value == null) {
          missing++;
        } else {
          sum += value * BigInt.from(term['coefficient'] as int);
        }
      }
      guard(
        current == sum && missing == eq['missingTermCount'],
        'bound printed subtotal identity changed',
      );
    }
    final profit = profile['core'][5] as Map;
    final sourceRows = RegExp(
      r'<tr\b[^>]*>([\s\S]*?)</tr>',
      caseSensitive: false,
    ).allMatches(raw[basis]!);
    final matched = sourceRows
        .where(
          (r) => r[1]!.replaceAll('\r\n', '\n') == profile['profitRawRowHTML'],
        )
        .toList();
    guard(matched.length == 1, 'exact own multiline profit row missing');
    final cells = RegExp(
      r'<t[dh]\b[^>]*>([\s\S]*?)</t[dh]>',
      caseSensitive: false,
    ).allMatches(matched.single[1]!).toList();
    final labels = cells[0][1]!
        .split(RegExp(r'<br\s*/?>', caseSensitive: false))
        .map(compact)
        .where((v) => v.isNotEmpty)
        .toList();
    final amounts = cells[3][1]!
        .split(RegExp(r'<br\s*/?>', caseSensitive: false))
        .map(compact)
        .where((v) => v.isNotEmpty)
        .toList();
    guard(
      labels.length == 3 &&
          labels[0] == (consolidated ? 'Ⅷ.연결당기순이익' : 'Ⅷ.당기순이익') &&
          labels[1] == '대손준비금반영후조정이익' &&
          labels[2] == '비상위험준비금반영후조정이익',
      'distinct profit labels missing',
    );
    guard(
      jsonEncode(amounts) ==
              jsonEncode(
                (profile['profitDefinitions'] as Map).values.toList(),
              ) &&
          amounts[0] == profit['selectedPrintedLine'] &&
          money(amounts[0]) == money(tables[10][2][2]),
      'own NI line/CF mismatch',
    );
    return [
      for (final cell in profile['core'] as List)
        _row(cell, tables, money, uris, guard, profile),
    ];
  }

  static Map<String, dynamic> _row(
    Map cell,
    List tables,
    BigInt? Function(String) money,
    Map<String, Uri> uris,
    void Function(bool, String) guard,
    Map<String, dynamic> profile,
  ) {
    final year = profile['year'] as int;
    final receipt = profile['receipt'] as String;
    final basis = profile['basis'] as String;
    final actual =
        tables[cell['table'] as int][cell['row'] as int][cell['column'] as int]
            as String;
    final selected = cell['selectedPrintedLine'] as String?;
    final printed = money(selected ?? actual);
    guard(
      printed != null && actual == cell['printed'],
      'direct current cell missing',
    );
    final value = cell['magnitude'] == true ? printed!.abs() : printed!;
    guard(
      value.toString() == cell['value'],
      'current normalized amount mismatch',
    );
    return {
      'rcept_no': receipt,
      'corp_code': '00113191',
      'bsns_year': '$year',
      'reprt_code': '11011',
      'fs_div': basis.toUpperCase(),
      'account_id': null,
      'account_nm': cell['label'],
      'account_detail': '-',
      'ord': '${cell['physicalOrd']}',
      'sj_div': cell['kind'],
      'thstrm_nm': cell['kind'] == 'BS'
          ? '$year-12-31'
          : '$year-01-01~$year-12-31',
      'thstrm_amount': value.toString(),
      'currency': 'KRW',
      'html_provenance': {
        'source': uris[basis].toString(),
        'sourceReceipt': receipt,
        'ruleVersion': rule,
        'sourceSha256': (profile['sources'] as List).singleWhere(
          (v) => v['label'] == basis,
        )['sha256'],
        'tableIndex': cell['table'],
        'rowIndex': cell['row'],
        'column': cell['column'],
        'physicalOrd': cell['physicalOrd'],
        'printedLabel': cell['label'],
        'printedPhysicalLabel':
            tables[cell['table'] as int][cell['row'] as int][0],
        'currentCell': actual,
        'selectedPrintedLine': selected,
        'multiLineProfitDefinitions': selected == null
            ? null
            : profile['profitDefinitions'],
        'printedUnit': '원',
        'unitMultiplier': '1',
        'precisionUnit': '1',
        'cashDirection': cell['magnitude'] == true ? 'outflow' : null,
        'printedSign': printed.isNegative ? 'negative' : 'positive',
        'basis': basis.toUpperCase(),
        'periodStart': '$year-01-01',
        'periodEnd': '$year-12-31',
        ...profile['scopeProof'] as Map<String, dynamic>,
        'fullStatementCollected': false,
        'supportingPeriodEvidence': {
          'policy': rule,
          'flowCaptionPrintedStart': true,
          'periodStart': '$year-01-01',
          'periodEnd': '$year-12-31',
          'scopeProof': profile['scopeProof'],
          'currentEquationWitnesses': profile['checks'],
        },
      },
    };
  }
}
